resource "aws_route53_record" "eu" {
  zone_id        = var.zone_id
  name           = "app.example.com"
  type           = "A"
  set_identifier = "eu"
  geolocation_routing_policy { continent = "EU" }
  alias { name = aws_lb.eu.dns_name, zone_id = aws_lb.eu.zone_id, evaluate_target_health = true }
}
